<template><div class="space-y-4"><el-input v-model="input" type="textarea" :rows="10" placeholder="每行一条文本"/><div class="flex flex-wrap gap-3"><el-select v-model="mode" class="w-40"><el-option label="升序" value="asc"/><el-option label="降序" value="desc"/><el-option label="按长度" value="length"/></el-select><el-input v-model="keyword" class="w-48" placeholder="过滤关键词"/><el-checkbox v-model="unique">去重</el-checkbox><el-checkbox v-model="removeEmpty">去空行</el-checkbox></div><el-button type="primary" size="small" @click="process">处理文本</el-button><el-input v-model="output" type="textarea" :rows="10" readonly/></div></template>
<script setup lang="ts">import { ref } from 'vue';const input=ref('');const output=ref('');const mode=ref('asc');const keyword=ref('');const unique=ref(true);const removeEmpty=ref(true);const process=()=>{let a=input.value.split(/\r?\n/);if(removeEmpty.value)a=a.filter(Boolean);if(keyword.value)a=a.filter(x=>x.includes(keyword.value));if(unique.value)a=[...new Set(a)];a.sort((x,y)=>mode.value==='length'?x.length-y.length:x.localeCompare(y,'zh-CN'));if(mode.value==='desc')a.reverse();output.value=a.join('\n')}</script>
